<script setup lang="ts">
import {Clock3,ExternalLink,Heart,MapPin} from 'lucide-vue-next'
const route=useRoute(); const {$supabase}=useNuxtApp(); const {data:place}=await useAsyncData(`place-${route.params.slug}`,async()=>{const {data,error}=await $supabase.from('place_cards').select('*').eq('slug',route.params.slug).single(); if(error) throw error; return data})
useSeoMeta({title:()=>place.value?.name||'Place',description:()=>place.value?.short_description||'Korea IRL place guide'})
</script>
<template><main v-if="place" class="mx-auto max-w-7xl px-5 py-10"><p class="text-sm text-[var(--brand-muted)]">Home / Seoul / {{place.neighborhood}}</p><div class="mt-5 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p class="text-sm text-[var(--brand-accent)]">{{place.category}}</p><h1 class="text-4xl font-semibold">{{place.name}}</h1></div><button class="inline-flex items-center gap-2 rounded-xl border border-[var(--brand-border)] bg-white px-4 py-3"><Heart class="h-4 w-4"/> Save</button></div><div class="mt-6 grid gap-5 lg:grid-cols-[1.5fr_.5fr]"><div><div class="aspect-[16/9] overflow-hidden rounded-3xl bg-neutral-200"><img v-if="place.cover_image_url" :src="place.cover_image_url" :alt="place.name" class="h-full w-full object-cover"/></div><div class="mt-6 rounded-3xl bg-white p-6"><h2 class="text-xl font-semibold">Why go</h2><p class="mt-3 leading-7 text-[var(--brand-muted)]">{{place.description}}</p></div></div><aside class="rounded-3xl border border-[var(--brand-border)] bg-white p-5 lg:self-start"><dl class="space-y-4 text-sm"><div class="flex gap-3"><MapPin class="h-5 w-5 shrink-0"/><div><dt class="font-medium">Address</dt><dd class="text-[var(--brand-muted)]">{{place.address}}</dd></div></div><div class="flex gap-3"><Clock3 class="h-5 w-5 shrink-0"/><div><dt class="font-medium">Hours</dt><dd class="text-[var(--brand-muted)]">{{place.opening_hours||'Check official source'}}</dd></div></div></dl><a v-if="place.official_url" :href="place.official_url" target="_blank" rel="noopener noreferrer" class="mt-5 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-[var(--brand-ink)] px-4 py-3 text-sm text-white">Official website <ExternalLink class="h-4 w-4"/></a><ClientOnly><PlaceMap v-if="place.latitude !== null && place.longitude !== null" :latitude="place.latitude" :longitude="place.longitude" :label="place.name" class="mt-5"/></ClientOnly></aside></div></main></template>
